"""Uniform loading of the Economo-lab data objects.

The `data_structure_*.mat` files come in two flavours: MATLAB v7.3 (HDF5) and
MATLAB v5.  This module loads either into the *same* nested-python structure:
    MATLAB struct  -> dict
    MATLAB cell    -> (nested) list
    MATLAB char    -> str
    numeric array  -> np.ndarray (MATLAB column-major orientation restored)
"""
import numpy as np
import h5py
import scipy.io as sio


def is_v73(fn):
    with open(fn, 'rb') as fh:
        return 'HDF5' in fh.read(128).decode('latin1')


# ----------------------------------------------------------------- v7.3 ----
def _h5_to_py(f, item):
    if isinstance(item, h5py.Group):
        if item.attrs.get('MATLAB_class', b'') == b'struct':
            # struct array?
            keys = list(item.keys())
            out = {k: _h5_to_py(f, item[k]) for k in keys}
            return out
        return {k: _h5_to_py(f, item[k]) for k in item.keys()}

    cls = item.attrs.get('MATLAB_class', b'').decode() if 'MATLAB_class' in item.attrs else ''
    if cls == 'char':
        a = np.array(item)
        if a.size == 0:
            return ''
        # char arrays saved as uint16, shape (nchar,1) or (1,nchar)
        if a.ndim == 2 and min(a.shape) == 1:
            return ''.join(chr(int(c)) for c in a.ravel())
        # multi-row char matrix
        a = a.T
        return [''.join(chr(int(c)) for c in row) for row in a]
    if item.dtype == object:  # cell array / struct array of refs
        a = np.array(item)
        out = np.empty(a.shape, dtype=object)
        for idx in np.ndindex(a.shape):
            r = a[idx]
            if isinstance(r, h5py.Reference) and r:
                out[idx] = _h5_to_py(f, f[r])
            else:
                out[idx] = None
        # MATLAB orientation: h5py gives transposed shape
        out = out.T
        return out
    if cls == 'logical':
        return np.array(item).T.astype(bool)
    return np.array(item).T


def load_v73(fn, field='obj'):
    f = h5py.File(fn, 'r')
    out = _h5_to_py(f, f[field])
    f.close()
    return out


# ------------------------------------------------------------------ v5 ----
def _mat_to_py(x):
    if isinstance(x, sio.matlab.mat_struct):
        return {k: _mat_to_py(getattr(x, k)) for k in x._fieldnames}
    if isinstance(x, np.ndarray) and x.dtype == object:
        out = np.empty(x.shape, dtype=object)
        for idx in np.ndindex(x.shape):
            out[idx] = _mat_to_py(x[idx])
        return out
    if isinstance(x, str):
        return x
    return x


def load_v5(fn, field='obj'):
    m = sio.loadmat(fn, struct_as_record=False, squeeze_me=True)
    return _mat_to_py(m[field])


def load_obj(fn, field='obj'):
    """Load a session data object from either mat file version."""
    if is_v73(fn):
        return load_v73(fn, field)
    return load_v5(fn, field)


def as_vector(x):
    """Return a 1-D float array from a MATLAB (1,N)/(N,1)/scalar field."""
    return np.atleast_1d(np.asarray(x, dtype=float)).ravel()


def as_cell_list(x, n=None):
    """Return list of length n from a MATLAB cell array (object ndarray)."""
    if isinstance(x, np.ndarray) and x.dtype == object:
        lst = list(x.ravel(order='F'))
    elif isinstance(x, list):
        lst = x
    else:
        lst = [x]
    return lst
