"""Parse the reference MATLAB meta scripts (DataLoadingScripts/Recording and video/*.m)
to get the authoritative list of ephys sessions and the probe(s) located in ALM."""
import os, re, glob

META_DIR = '/app/code/DataLoadingScripts/Recording and video'
DATA_DIRS = ['/app/data/Ephys_Behavior', '/app/data/RandomizedDelay_Ephys_Behavior']


def parse_meta_scripts(meta_dir=META_DIR):
    sessions = []
    for fn in sorted(glob.glob(os.path.join(meta_dir, '*.m'))):
        cur = None
        for line in open(fn):
            l = line.strip()
            if l.startswith('%'):
                continue
            l = l.split('%')[0]
            m = re.search(r"meta\(end(?:\+1)?\)\.anm\s*=\s*'([^']+)'", l)
            if m:
                if '+1' in l or cur is None:
                    cur = {'anm': m.group(1)}
                    sessions.append(cur)
                else:
                    cur['anm'] = m.group(1)
                continue
            m = re.search(r"meta\(end(?:\+1)?\)\.date\s*=\s*'([^']+)'", l)
            if m:
                if '+1' in l:
                    cur = {'anm': sessions[-1]['anm'] if sessions else None,
                           'date': m.group(1)}
                    sessions.append(cur)
                else:
                    cur['date'] = m.group(1)
                continue
            m = re.search(r"meta\(end(?:\+1)?\)\.probe\s*=\s*(\[[^\]]*\]|\d+)", l)
            if m:
                p = m.group(1)
                probes = [int(x) for x in re.findall(r'\d+', p)]
                cur['probe'] = probes
                continue
            m = re.search(r"meta\(end\+1\)\.datapth", l)
            if m:
                cur = {}
                sessions.append(cur)
    # clean: an entry created by datapth line gets filled by following anm/date/probe
    out = []
    for s in sessions:
        if 'anm' in s and 'date' in s and 'probe' in s:
            out.append(s)
    # dedupe
    seen = set()
    uniq = []
    for s in out:
        k = (s['anm'], s['date'])
        if k in seen:
            continue
        seen.add(k)
        uniq.append(s)
    return uniq


def find_data_file(anm, date):
    for d in DATA_DIRS:
        fn = os.path.join(d, f'data_structure_{anm}_{date}.mat')
        if os.path.exists(fn):
            return fn
    return None


def find_me_file(anm, date):
    for d in DATA_DIRS:
        fn = os.path.join(d, f'motionEnergy_{anm}_{date}.mat')
        if os.path.exists(fn):
            return fn
    return None


def get_sessions():
    """Return list of dicts with anm, date, probe, datafile, mefile for sessions
    that are listed in the reference meta scripts AND present in /app/data."""
    out = []
    for s in parse_meta_scripts():
        f = find_data_file(s['anm'], s['date'])
        if f is None:
            continue
        s = dict(s)
        s['datafile'] = f
        s['mefile'] = find_me_file(s['anm'], s['date'])
        s['dataset'] = ('randomized_delay' if 'RandomizedDelay' in f else 'fixed_delay')
        s['sessid'] = f"{s['anm']}_{s['date']}"
        out.append(s)
    return out


if __name__ == '__main__':
    allm = parse_meta_scripts()
    print('meta entries:', len(allm))
    have = get_sessions()
    print('with data present:', len(have))
    from collections import Counter
    print('by dataset:', Counter(s['dataset'] for s in have))
    print('animals:', sorted(set(s['anm'] for s in have)))
    print('fixed-delay animals:', sorted(set(s['anm'] for s in have if s['dataset']=='fixed_delay')))
    print('rand-delay animals:', sorted(set(s['anm'] for s in have if s['dataset']=='randomized_delay')))
    missing = [ (s['anm'],s['date']) for s in allm if find_data_file(s['anm'],s['date']) is None]
    print('meta sessions without data files:', missing)
    # data files not in meta
    import glob, os
    inmeta = set((s['anm'],s['date']) for s in allm)
    extra=[]
    for d in DATA_DIRS:
        for f in sorted(glob.glob(os.path.join(d,'data_structure_*.mat'))):
            b=os.path.basename(f)[len('data_structure_'):-4]
            anm,date=b.split('_')
            if (anm,date) not in inmeta: extra.append((d.split('/')[-1],anm,date))
    print('data files not listed in meta:', extra)
    for s in have: print(s['dataset'], s['anm'], s['date'], s['probe'], os.path.basename(s['mefile']) if s['mefile'] else 'NO_ME')
